from pathlib import Path
import csv,json,hashlib,collections
r=Path(__file__).resolve().parents[1];controls={int(x['id']):x for x in csv.DictReader((r/'build/ngk-controls.csv').open())};pred=list(csv.DictReader((r/'build/ngk-final-predictions.csv').open()));metrics=json.loads((r/'build/ngk-metrics.json').read_text());protocol=json.loads((r/'build/ngk-protocol.json').read_text())
assert len(pred)==89
assert all(hashlib.sha256((r/p).read_bytes()).hexdigest()==sha for p,sha in protocol['source_sha256'].items())
assert hashlib.sha256((r/'n-gk/TVM_Measurement_Data_Base.sq3').read_bytes()).hexdigest()=='0a1923cf6cda023fae422b8318388047f74e605741fd951108b6f7a3e2ebba21'
learn=list(csv.DictReader((r/'build/volume-audit-3.3.csv').open()));assert len(learn)==69 and all(not x['error'] and float(x['self_m3'])==0 for x in learn)
records=[]
for p in sorted(pred,key=lambda x:int(x['id'])):
 c=controls[int(p['id'])];t=float(c['total']);a=float(p['old']);b=float(p['new'])
 records.append(dict(MeasurementID=int(p['id']),TruckID=c['truck'],split=c['split'],TotalVolume=t,old_m3=a,new_m3=b,old_error_m3=a-t,new_error_m3=b-t,old_error_percent=(a/t-1)*100,new_error_percent=(b/t-1)*100,rim_correction_native=float(p['correction'])))
with (r/'NGK-comparison.csv').open('w',newline='',encoding='utf-8-sig') as f:
 w=csv.DictWriter(f,fieldnames=list(records[0]));w.writeheader();w.writerows(records)
lines=['# LaseScanViewer 3.3 — сравнение с TotalVolume','',
'Контроль: поле `LaseTVM.TotalVolume` в `n-gk/TVM_Measurement_Data_Base.sq3`, указанное пользователем как конечный измеренный объём. Проверяется соответствие этому контролю, а не независимая метрологическая точность сканера. Все м³ рассчитаны при масштабе 0,001 м на единицу координат.','',
'## Сопоставление и протокол','',
'- 164 файла Full; 89 пар с Empty того же номера, положительным TotalVolume и Status=5. В этих 89 строках TrailerVolume не положителен: сравнение относится к одному кузову. 75 Full без одноимённого Empty исключены, база Reference не содержит заменяющего облака точек.',
'- Ключ сопоставления — MeasurementID. Тест также проверяет номера, типы Full/Empty и одинаковую метку автомобиля внутри двух BIN.',
'- Разбиение выполнено до подбора параметров: SHA256(TruckID) mod 4 = 0 — отложенная группа. 62 пары разработки и 27 отложенных; автомобили не пересекаются между группами. Это проверка на других автомобилях той же площадки, не на независимом объекте.',
'- Рассмотрены максимум, среднее, минимум, медиана, квантили 10/25/75% на группе разработки. Выбран квантиль 10% с линейной интерполяцией и медианой при <10 точках. Исходный код геометрического алгоритма зафиксирован до оценки отложенной группы; хеши в NGK-protocol.json.',
'- Для пар использованы сохранённые исходные жёсткие преобразования 3.2.1; затем применено новое геометрическое уточнение Z. Оно не меняет выбранный угол/XY и не использует контроль. Работа полного нового поиска с этим этапом дополнительно проверена через x64/x86 приложение на 14184 и 14149.',
'- База открывалась только для чтения. Исполняемый файл не читает TotalVolume и не содержит таблицы контрольных объёмов, коэффициентов по TruckID или подстановки ответа.','',
'## Метрики','',
'MAE — средняя абсолютная разность в м³. MAPE — среднее абсолютное относительное расхождение по отдельным измерениям.','',
'| Группа | Версия | Пар | MAE, м³ | MAPE | Максимальное расхождение | Не более 5% |','|---|---|---:|---:|---:|---:|---:|']
for split in ['development','holdout']:
 for v in ['old','new']:
  m=metrics[split][v];lines.append(f'| {"Разработка" if split=="development" else "Отложенная"} | {"3.2.1" if v=="old" else "3.3.0"} | {m["n"]} | {m["mae_m3"]:.3f} | {m["mape_percent"]:.2f}% | {m["max_ape_percent"]:.2f}% | {m["within_5_percent"]} |')
lines += ['', '## Что изменилось', '', '1. Высота Empty уточняется по верхней части кузова: минимум 30 общих ячеек с достаточным покрытием по двум осям, ограничением остатка и проверкой медианного абсолютного отклонения. Поправка может быть положительной или отрицательной. При недостатке опор она не применяется. Этап включён для Full/Empty, не для Reference.', '2. В плотных ячейках используется нижняя поверхность, чтобы смесь точек стенки и дна меньше завышала Empty. При малом числе точек остаётся медиана. Все прежние оценки поверхности доступны в настройках.', '3. Прогресс, пять разрешений, предварительный расчёт при ненадёжном совмещении, ROI, серое окружение и экспорт сохранены.', '', '## Все измерения', '', '| ID | Группа | TotalVolume, м³ | До, м³ | После, м³ | Ошибка после, % (со знаком) |','|---|---|---:|---:|---:|---:|']
for x in records:lines.append(f'| {x["MeasurementID"]} | {"Отложенная" if x["split"]=="holdout" else "Разработка"} | {x["TotalVolume"]:.3f} | {x["old_m3"]:.3f} | {x["new_m3"]:.3f} | {x["new_error_percent"]:+.2f}% |')
lines += ['', '## Проверки и ограничения', '', '- Пройдены аналитические объёмы, одиночные выбросы, разрывы, ROI, квантиль/малые выборки, известная поправка Z и отклонение недостаточных опор, повороты 37°/180° с шумом. Все 69 прежних пар Learn пересчитаны без ошибок; каждый Empty против себя даёт нулевой груз. Для Learn контрольных объёмов нет.', '- x64/x86 проверены на BIN из n-gk с реальным поиском совмещения, расчётом, прогрессом, экспортом и сохранностью камеры/сканов.', '- Нижний квантиль устойчив к единичным низким выбросам в достаточно плотной ячейке, но при многочисленных низких ошибочных точках может завысить груз. Верхние опоры тоже могут быть перекрыты грузом. В таких случаях сравните медиану, наложение и область расчёта.', '- Средняя ошибка 1,34% на отложенных данных не гарантирует её для любого файла. Наихудшая ошибка этой группы — 6,29%; при других кузовах, масштабе и условиях возможна большая ошибка. Исходные ограничения 2.5D, наклона и больших пробелов сохраняются.', '', 'Сырые данные: NGK-comparison.csv. Контрольные строки и разбиение: NGK-controls.csv. Снимок исходных преобразований: NGK-baseline.csv. Для воспроизведения — scripts/prepare_ngk.py, tests/ngk_benchmark.cpp, scripts/evaluate_ngk.py. Исходный алгоритм 3.2.1 сохранён в предыдущем релизе; его базовые результаты приложены.']
(r/'NGK-audit.md').write_text('\n'.join(lines)+'\n',encoding='utf-8');print('Report complete; frozen algorithm and unchanged DB hashes verified')
